solution.solution.cpp:
#include <cstddef>
#include <vector>

struct Member { std::size_t size; std::size_t align; };

struct Layout
{
    std::vector<std::size_t> offsets;
    std::size_t size{ 0 };
    std::size_t align{ 1 };
};

static std::size_t roundUp(std::size_t value, std::size_t multiple)
{
    return (value + multiple - 1) / multiple * multiple;
}

Layout layout(const std::vector<Member>& members)
{
    Layout result;
    std::size_t at{ 0 };
    for (const Member& m : members)
    {
        at = roundUp(at, m.align);
        result.offsets.push_back(at);
        at += m.size;
        if (m.align > result.align) result.align = m.align;
    }
    result.size = roundUp(at, result.align);
    return result;
}

unitTests:
using V = std::vector<std::size_t>;
TEST("the wasteful pickup")
{
    const Layout l{ layout({ { 1, 1 }, { 4, 4 }, { 1, 1 }, { 8, 8 } }) };
    CHECK(l.offsets == V{ 0, 4, 8, 16 });
    CHECK_EQ(l.size, std::size_t{ 24 });
    CHECK_EQ(l.align, std::size_t{ 8 });
}
TEST("the tidy pickup")
{
    const Layout l{ layout({ { 8, 8 }, { 4, 4 }, { 1, 1 }, { 1, 1 } }) };
    CHECK(l.offsets == V{ 0, 8, 12, 13 });
    CHECK_EQ(l.size, std::size_t{ 16 });
}
TEST("tail padding") { const Layout l{ layout({ { 4, 4 }, { 1, 1 } }) }; CHECK_EQ(l.size, std::size_t{ 8 }); CHECK_EQ(l.align, std::size_t{ 4 }); }
TEST("only chars") { const Layout l{ layout({ { 1, 1 }, { 1, 1 }, { 1, 1 } }) }; CHECK(l.offsets == V{ 0, 1, 2 }); CHECK_EQ(l.size, std::size_t{ 3 }); CHECK_EQ(l.align, std::size_t{ 1 }); }
TEST("a short after a char") { const Layout l{ layout({ { 1, 1 }, { 2, 2 }, { 1, 1 } }) }; CHECK(l.offsets == V{ 0, 2, 4 }); CHECK_EQ(l.size, std::size_t{ 6 }); }
TEST("an array member: 3 ints count as size 12, align 4") { const Layout l{ layout({ { 1, 1 }, { 12, 4 } }) }; CHECK(l.offsets == V{ 0, 4 }); CHECK_EQ(l.size, std::size_t{ 16 }); }
TEST("an over-aligned member") { const Layout l{ layout({ { 4, 4 }, { 16, 16 } }) }; CHECK(l.offsets == V{ 0, 16 }); CHECK_EQ(l.size, std::size_t{ 32 }); CHECK_EQ(l.align, std::size_t{ 16 }); }
TEST("an empty struct") { const Layout l{ layout({}) }; CHECK(l.offsets.empty()); CHECK_EQ(l.size, std::size_t{ 0 }); CHECK_EQ(l.align, std::size_t{ 1 }); }

